//! Synthetic projection volume tests, separate from actual scientific/public
//! record acceptance. No fake data is installed on a deployment.
use flypow::{explorer::query_index,explorer_types::*,explorer_projection};
use rusqlite::{Connection,params};use serde_json::json;
fn database(path:&std::path::Path,count:usize)->Connection{let mut c=Connection::open(path).unwrap();c.execute_batch(include_str!("../config/explorer-v1.sql")).unwrap();let tx=c.transaction().unwrap();
 for(k,v)in [("asOf",flypow::target_authority::now().to_string()),("indexVersion",INDEX_VERSION.into())]{tx.execute("INSERT INTO explorer_meta VALUES(?,?)",params![k,v]).unwrap();}
 tx.execute("INSERT INTO explorer_meta VALUES('overview',?)",[json!({"fixture":true,"network":{},"supply":{},"metrics":{},"chainStatus":"NOT_CONFIGURED","chainNamespaces":[]}).to_string()]).unwrap();
 for i in 1..=count{let id=format!("{i:064x}");let v=json!({"schemaVersion":1,"recordId":id,"goalId":"a".repeat(64),"modelRoot":"b".repeat(64),"minerId":"c".repeat(64),"status":"valid-winner","displaySequence":i.to_string(),"researchGoal":{"en":"Synthetic volume fixture only","zh":"仅用于规模测试的合成夹具"},"padding":"x".repeat(700)});explorer_projection::put(&tx,"target-v2","record",&id,i as i64,i as i64,&v).unwrap();}tx.commit().unwrap();c}
#[test]fn cursor_is_bound_to_filter_and_snapshot_and_search_is_typed(){let dir=tempfile::tempdir().unwrap();let c=database(&dir.path().join("index.sqlite"),101);let first=query_index(&c,"records",&ExplorerQuery{limit:20,..Default::default()}).unwrap();let mut cursor=first["nextCursor"].as_str().unwrap().to_string();
 explorer_projection::put(&c,"target-v2","record",&format!("{:064x}",102),102,102,&json!({"recordId":format!("{:064x}",102),"status":"valid-winner"})).unwrap();let mut ids=first["items"].as_array().unwrap().iter().map(|v|v["recordId"].as_str().unwrap().to_string()).collect::<Vec<_>>();loop{let next=query_index(&c,"records",&ExplorerQuery{cursor:cursor.clone(),limit:20,..Default::default()}).unwrap();ids.extend(next["items"].as_array().unwrap().iter().map(|v|v["recordId"].as_str().unwrap().to_string()));if next["hasMore"]!=true{break;}cursor=next["nextCursor"].as_str().unwrap().into();}
 assert_eq!(ids.len(),101);let unique=ids.iter().collect::<std::collections::BTreeSet<_>>();assert_eq!(unique.len(),101);assert!(!ids.contains(&format!("{:064x}",102)));assert!(query_index(&c,"records",&ExplorerQuery{cursor:first["nextCursor"].as_str().unwrap().into(),status:"invalid".into(),..Default::default()}).is_err());
 let hex=format!("{:064x}",100);let search=query_index(&c,"search",&ExplorerQuery{q:hex,..Default::default()}).unwrap();assert_eq!(search["data"]["matches"][0]["objectType"],"record");let number=query_index(&c,"search",&ExplorerQuery{q:"100".into(),..Default::default()}).unwrap();assert!(number["data"]["hints"].as_array().unwrap().len()>=2);
 assert_eq!(base58_width("11111111111111111111111111111111"),Some(32));assert_eq!(base58_width("00000000"),None);let bad=query_index(&c,"search",&ExplorerQuery{q:"<img src=x onerror=alert(1)>".into(),..Default::default()}).unwrap();assert!(bad["data"]["matches"].as_array().unwrap().is_empty());assert!(query_index(&c,"chains/unconfigured/blocks/100",&ExplorerQuery::default()).unwrap_err().starts_with("NOT_CONFIGURED"));}
#[test]fn hundred_thousand_metadata_records_are_paged_without_full_scan(){let root=std::path::PathBuf::from("data/prepared/explorer-20261012");std::fs::create_dir_all(&root).unwrap();let path=root.join("volume.sqlite");let c=if path.is_file(){let c=Connection::open(&path).unwrap();assert_eq!(c.query_row("SELECT COUNT(*) FROM explorer_objects",[],|r|r.get::<_,i64>(0)).unwrap(),100_000);c}else{database(&path,100_000)};let mut durations=Vec::new();for _ in 0..100{let start=std::time::Instant::now();let v=query_index(&c,"records",&ExplorerQuery{limit:20,goal_id:"a".repeat(64),..Default::default()}).unwrap();assert_eq!(v["items"].as_array().unwrap().len(),20);durations.push(start.elapsed().as_secs_f64()*1000.0);}durations.sort_by(f64::total_cmp);let report=json!({"schema":"explorer-volume-acceptance-v1","environment":"isolated synthetic public metadata projection; not real scientific records","records":100_000,"recordApproxBytes":1000,"queries":100,"limit":20,"p50Ms":durations[50],"p95Ms":durations[95],"targetP95Ms":200,"passed":durations[95]<200.0,"actualContainerCpuQuota":std::fs::read_to_string("/sys/fs/cgroup/cpu.max").unwrap_or_default().trim(),"actualContainerMemoryMax":std::fs::read_to_string("/sys/fs/cgroup/memory.max").unwrap_or_default().trim()});std::fs::write(root.join("volume-query.json"),serde_json::to_string_pretty(&report).unwrap()).unwrap();assert!(durations[95]<200.0,"actual p95={}ms",durations[95]);}
